look.template_css:
/* A theme as CSS: the words between two at-signs are placeholders filled from the fixed tables in themes.py (ADR 0028). */
.card { background:@light.background@; }
.card.nightMode, .card.night_mode { background:@night.background@; }
.av { --ink:@light.text@; --sub:@light.secondary@; --bg:@light.background@; --name:@light.name@; --accent:@light.accent@; --credits:@light.credits@; --radius:@corners@;
  font-family:@font@; }
.nightMode .av, .night_mode .av { --ink:@night.text@; --sub:@night.secondary@; --bg:@night.background@; --name:@night.name@; --accent:@night.accent@; --credits:@night.credits@; }
.photo img { border-radius:var(--radius); }
.name { color:var(--name); font-weight:@name_weight@; @name_style@ }
.ioc-tag { border-color:color-mix(in srgb, var(--accent) 70%, transparent); background:color-mix(in srgb, var(--accent) 10%, transparent); }
.credits { color:var(--credits); border-top-color:color-mix(in srgb, var(--credits) 35%, transparent); }
@rule@

themes.extra_css:
.ioc-tag { color:var(--sub); border-color:var(--accent); background:color-mix(in srgb, var(--accent) 14%, transparent); }
.credits { background:#e5e9f0; border:0; border-radius:8px; padding:8px 10px; }
.nightMode .credits, .night_mode .credits { background:#3b4252; }
.photo img { box-shadow:0 1px 3px rgba(46,52,64,.25); }
.nightMode .photo img, .night_mode .photo img { box-shadow:none; }

.av { text-align:center; }
.av .names { border-top:3px double var(--accent); border-bottom:3px double var(--accent); padding:10px 0; }
.name { font-style:italic; }
.sound { justify-content:center; }
.credits { text-align:center; border-top-style:dotted; }

.av { font-size:19px; }
.sci, .sound-label, .prompt { color:var(--ink); }
.ioc-tag { font-size:12px; border-width:2px; color:var(--ink); }
.credits { font-size:13px; border-top:2px solid var(--ink); color:var(--ink); }

layout_css.name_on_photo:
/* Layout "name on the photo" (ADR 0028): on the back the tag, name and scientific name sit on a dark
   gradient over the bottom of the picture. The photo is sized by the picture itself on both sides so
   the gradient never overhangs a tall photo and the photo stays put when the card flips (ADR 0025).
   A very wide picture is cropped to a minimum height so the names always fit on it. */
.av .photo { position:relative; width:fit-content; max-width:100%; margin:0 auto; }
.av .photo img { width:auto; height:auto; max-width:100%; max-height:46vh; min-height:130px; object-fit:cover; }
.av .photo .names { position:absolute; left:0; right:0; bottom:0; margin:0; padding:22px 14px 12px; box-sizing:border-box;
  --ink:#fff; --sub:#e9ecef; --name:#fff; --accent:#fff; border:0; color:#fff; text-shadow:0 1px 3px rgba(0,0,0,.55);
  background:linear-gradient(to top, rgba(0,0,0,.84) 0%, rgba(0,0,0,.68) 62%, rgba(0,0,0,0) 100%);
  border-radius:0 0 var(--radius,10px) var(--radius,10px); }
.av .photo .names .name { font-size:1.45em; }
.av .photo .names .ioc-tag { background:rgba(0,0,0,.35); }
